// 우리가 못 바꾸는 헤더 (브라우저가 정한다)
//   Origin · Referer · Host · Cookie · User-Agent · Content-Length
// 이것들은 코드로 못 덮어쓴다 — 그래서 서버가 믿을 수 있는 근거가 된다

// 여러 요청이 동시에 401 을 받으면 갱신이 여러 번 일어난다 (동시성 5장)
let refreshing = null;
async function withAuth(req) {
  let res = await req();
  if (res.status === 401) {
    refreshing ??= refresh().finally(() => { refreshing = null; });   // 한 번만
    await refreshing;
    res = await req();
  }
  return res;
}

const ALLOWED = new Set(['https://mysite.com', 'https://staging.mysite.com']);

app.use((req, res, next) => {
  const origin = req.headers.origin;
  if (ALLOWED.has(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);   // * 아님
    res.setHeader('Vary', 'Origin');                         // 캐시가 섞이지 않게
    res.setHeader('Access-Control-Allow-Credentials', 'true');
  }
  if (req.method === 'OPTIONS') {
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
    res.setHeader('Access-Control-Max-Age', '600');
    return res.status(204).end();
  }
  next();
});

// ① 캐시 우선 — 절대 안 바뀌는 자산 (해시 파일명)
caches.match(req).then((hit) => hit ?? fetch(req));

// ② 네트워크 우선 — 최신이 중요한 것 (API)
fetch(req).catch(() => caches.match(req));

// ③ 오래된 것 먼저 보여 주고 뒤에서 갱신 (stale-while-revalidate)
const hit = await caches.match(req);
const fresh = fetch(req).then((res) => { cache.put(req, res.clone()); return res; });
return hit ?? fresh;

