async function api(path, { schema, timeout = 8000, retries = 2, ...init } = {}) {
  for (let i = 0; ; i++) {
    try {
      const res = await fetch(path, {
        credentials: 'include',                       // 쿠키 (2장)
        signal: AbortSignal.timeout(timeout),
        ...init,
      });
      if (res.status === 401) throw new AuthError();   // 갱신 흐름으로 (3장)
      if (!res.ok) throw new HttpError(res.status);    // 4xx/5xx 구분 (cs-net 5장)
      return schema ? schema.parse(await res.json()) : res;   // 경계 검증 (TS 5장)
    } catch (e) {
      if (i >= retries || !isRetriable(e)) throw e;
      await sleep(2 ** i * 200 * (0.5 + Math.random()));      // 백오프 + 흔들기
    }
  }
}
